mapper.select:
SELECT ty.id, ty.year, ty.dept_id, ty.dept_name, ty.create_user_name, ty.create_time FROM bi_target_year ty WHERE ty.is_deleted=false
AND ty.year =#{params.year}
AND ty.dept_id =#{params.deptId}
AND ty.id IN ( SELECT main_id FROM bi_target_shop_setting WHERE is_deleted=FALSE AND metrics = #{params.metrics} )
AND ty.id IN ( SELECT main_id FROM bi_target_shop_setting WHERE is_deleted=FALSE AND shop_name ILIKE concat('%', #{params.name} ,'%') )
${params.permissionSql}
ORDER BY ty.id DESC

select btss.shop_name as typeName, btss.month, btss.value from bi_target_year bty left join bi_target_shop_setting btss on btss.is_deleted = false and bty.id = btss.main_id
bty.is_deleted = false
and btss.metrics = #{params.metrics}
and bty.year = to_char(#{params.startTime},'yyyy')::INTEGER and btss.month between 1 and 12
and bty.dept_id in
#{item}
and btss.shop_name in
#{item}

SELECT month, SUM(tss.value) AS value FROM bi_target_year ty INNER JOIN bi_target_shop_setting tss ON ty.id=tss.main_id and tss.is_deleted=false WHERE ty.is_deleted=false
AND ty.year =#{params.year}
AND ty.dept_id =#{params.deptId}
AND tss.metrics = #{params.metrics}
AND tss.staff_name ILIKE concat('%', #{params.name} ,'%')
${params.permissionSql}
GROUP BY month
